.darma-loader-three-dots-stretching{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.darma-loader-three-dots-stretching i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-stretching i{animation:darma-loader-three-dots-stretching-td-stretch-mid var(--loader-speed, 1.4s) infinite ease-in-out}
.darma-loader-three-dots-stretching i:nth-child(1){animation-name:darma-loader-three-dots-stretching-td-stretch-left}
.darma-loader-three-dots-stretching i:nth-child(3){animation-name:darma-loader-three-dots-stretching-td-stretch-right}
@keyframes darma-loader-three-dots-stretching-td-stretch-left{
  0%,100%{transform:translateX(0) scale(.75)}
  50%{transform:translateX(calc(var(--loader-size, 56px) / -6)) scale(1)}
}
@keyframes darma-loader-three-dots-stretching-td-stretch-mid{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.25)}
}
@keyframes darma-loader-three-dots-stretching-td-stretch-right{
  0%,100%{transform:translateX(0) scale(.75)}
  50%{transform:translateX(calc(var(--loader-size, 56px) / 6)) scale(1)}
}

